5		openD110cARepeatCloseFixture,
6	} from "../phase-6b-d110c-a/repeat-close-contract.js";
7	
8	export const D110C_0C1F5_FOREIGN_AUTHOR_CLOSE_LIVENESS_REQUIRED =
9		"D110C_0C1F5_FOREIGN_AUTHOR_CLOSE_LIVENESS_REQUIRED" as const;
10	
11	const LEGACY_MULTI_AUTHOR_MIGRATION_REQUIRED = "D110C_0C1F1_LEGACY_MULTI_AUTHOR_MIGRATION_REQUIRED";
