16	type RepeatCloseContext = Parameters<NonNullable<D110cARepeatCloseOptions["beforeRepeatCloseBinding"]>>[0];
17	
18	function errorMessage(error: unknown): string {
19		return error instanceof Error ? error.message : String(error);
20	}
21	
22	function acceptedIssue(
23		result: V3LocalIssueResult,
24		label: string
25	): Readonly<{ authorSequence: number; digest: string }> {
26		if (result.ok !== true) throw new TypeError(`${label}:${result.kind}`);
27		return Object.freeze({ authorSequence: result.authorSequence, digest: result.digest });
28	}
29	
30	function twoWriterAuthorities(): Readonly<{
31		readonly creator: ReturnType<typeof d108d1bChatAuthorities>[number];
32		readonly foreign: ReturnType<typeof d108d1bChatAuthorities>[number];
33	}> {
34		const authorities = d108d1bChatAuthorities();
35		const creator = authorities.find(({ id }) => id === "alice");
36		const foreign = authorities.find(({ id }) => id === "bob");
37		if (creator === undefined || foreign === undefined) {
38			throw new TypeError("D110C_0C1F5_TWO_WRITER_AUTHORITY_UNAVAILABLE");
39		}
40		return Object.freeze({ creator, foreign });
41	}
42	
43	async function routeVertex(
44		context: RepeatCloseContext,
45		input: Readonly<{
46			readonly authorSequence: number;
47			readonly dependency?: string;
48			readonly logicalTime: number;
49			readonly privateKeySeedHex: string;
50			readonly value: number;
51		}>
52	): Promise<void> {
53		const vertex = context.createRegisteredVertex({
54			anchor: context.currentAnchorDigest,
55			authorSequence: input.authorSequence,
56			dependencies: [input.dependency ?? context.latestDependencyDigest],
57			epoch: context.currentEpoch,
58			logicalTime: input.logicalTime,
59			objectId: context.plane.objectId,
60			operation: Object.freeze({ action: "add", value: input.value }),
61			privateKeySeedHex: input.privateKeySeedHex,
62		});
63		await context.routeRegisteredVertex(vertex, `d110c-0c1f5-${input.logicalTime}`);
64	}
65	
66	async function observedCloseError(options: D110cARepeatCloseOptions, expected: string, label: string): Promise<void> {
67		try {
68			const fixture = await openD110cARepeatCloseFixture({ ...options, retainedControls: false });
69			await fixture.close();
70			throw new TypeError(`${label}:UNEXPECTED_CLOSE_SUCCESS`);
71		} catch (error) {
72			const observed = errorMessage(error);
73			if (observed !== expected) {
74				throw new TypeError(`${label}:NONCAUSAL_ERROR:${observed}`);
75			}
76		}
77	}
78	
79	function revokedForeignCreatorOptions(
80		creator: ReturnType<typeof d108d1bChatAuthorities>[number],
81		foreign: ReturnType<typeof d108d1bChatAuthorities>[number]
82	): NonNullable<D110cARepeatCloseOptions["creator"]> {
