105	function exactFrontiers(record: Readonly<Record<string, unknown>>): readonly (readonly [string, number | null])[] {
106		if (!Array.isArray(record.frontiers)) throw new TypeError("D110C_0C1F5_FRONTIERS_UNAVAILABLE");
107		return record.frontiers.map((entry) => {
108			if (
109				!Array.isArray(entry) ||
110				entry.length !== 2 ||
111				typeof entry[0] !== "string" ||
112				(entry[1] !== null && !Number.isSafeInteger(entry[1]))
113			) {
114				throw new TypeError("D110C_0C1F5_FRONTIER_ENTRY_INVALID");
115			}
116			return Object.freeze([entry[0], entry[1] as number | null] as const);
117		});
118	}
